import{_ as o,l as i,o as e,c as s,v as t,p as l,x as r,d as E,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"风险的期限结构","description":"","frontmatter":{"title":"风险的期限结构","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/term-structure-of-risk.md","filePath":"econ/term-structure-of-risk.md","lastUpdated":1789023840000}'),p={name:"econ/term-structure-of-risk.md"};function c(B,a,_,h,u,A){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="风险的期限结构" tabindex="-1">风险的期限结构 <a class="header-anchor" href="#风险的期限结构" aria-label="Permalink to &quot;风险的期限结构&quot;">​</a></h1><div class="epigraph"><p>同一资产的短现金流与长现金流可以带着不同的风险价格；股权溢价不必在期限上平坦。</p><footer>—— 据 Lettau and Wachter, Why Is Long-Horizon Equity Less Risky? Journal of Finance, 2007；van Binsbergen, Brandt and Koijen, Journal of Finance, 2012</footer></div><p><a href="/econ/dp-ratio-predictability">上一课</a>把 \\(D/P\\) 当成折现率状态的一个总量坐标。本课缺口是<strong>沿期限切开</strong>：价格是许多到期现金流之和，每一条「股利条」可以有自己的风险溢价。不重做预测回归，不把国债的仿射期限结构整课搬进来——那是主干 EH / 仿射课的对象；这里是<strong>股权风险</strong>的期限结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>恒定折现时，长股利只是多折几期，风险若只来自股利水平，长久期更险。时变折现翻转直觉：长现金流对折现率冲击更敏感，若折现率冲击可对冲或与 \\(m\\) 的协方差符号相反，长股权条的溢价可以更低。Lettau–Wachter 给出一种模型：折现率均值回复，股利增长的永久冲击才是「坏」，于是短股利条（尚未被折现率平均掉）可以更险。van Binsbergen 等把股权拆成股利期货式的要求权，是测量；本课只要理论许可：风险价格可以随到期变。</p><p>缺口不是再校准 \\(\\gamma\\)，而是：总量股权溢价是各条期限溢价的加权，Shiller 波动与 \\(D/P\\) 预测主要抓住折现率因子，短现金流可能另有一块股利风险。</p><p><span class="marginnote">股利条（dividend strip）：只领取某一年股利的要求权。完全市场里可用期权或期货合成；不完全则是理论对象。本课不写合成的执行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 \\(P_t=\\sum_{n=1}^\\infty P_t^{(n)}\\)，其中 \\(P^{(n)}\\) 为 \\(n\\) 期后股利的现值。对每一条写 \\(1=\\mathrm{E}_t[m_{t,t+n} D_{t+n}/P_t^{(n)}]\\)，溢价 \\(\\mathrm{E}[R^{(n)}]-r_f^{(n)}\\) 由 \\(m_{t,t+n}\\) 与 \\(D_{t+n}\\) 的协方差决定。\\(m\\) 的单因子结构会让期限结构由该因子的久期决定；多因子（习惯的慢状态、长期风险的持续增长）给出更富的形状。</p><p>与债券：名义无违约债券的期限结构是 \\(m\\) 对一单位计价物的价格；股权条是 \\(m\\) 对随机股利的价格。两者共享 \\(m\\)，不共享支付。不要把股权溢价的期限结构写成国债 EH 的否证。</p>',10)),(e(),l(m,null,{default:r(()=>[d(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%82%A1%E6%9D%83%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20STRIP%5B%22%E8%82%A1%E5%88%A9%E6%9D%A1%20P%5E(n)%22%5D%0A%20%20M%5B%22%E6%A0%B8%20m%22%5D%20--%3E%20TS%5B%22%E5%90%84%E5%88%B0%E6%9C%9F%E8%87%AA%E5%B7%B1%E7%9A%84%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20STRIP%20--%3E%20TS%0A%20%20DR%5B%22%E6%8A%98%E7%8E%B0%E7%8E%87%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20LONG%5B%22%E9%95%BF%E4%B9%85%E6%9C%9F%E6%9B%B4%E6%95%8F%E6%84%9F%22%5D%0A%20%20CF%5B%22%E8%82%A1%E5%88%A9%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20SHORT%5B%22%E7%9F%AD%E6%9D%A1%E6%9A%B4%E9%9C%B2%E6%B0%B8%E4%B9%85%E5%A2%9E%E9%95%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Lucas 树单状态 Markov 已经给出一条期限结构，只是通常被加总藏掉。本课把加总拆开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是不同到期对状态冲击的暴露。均值回复的折现率：长期看被平均，短中期条承担「现在 \\(m\\) 很抖」。持久的增长冲击：所有条都暴露，但短条折现少、相对权重更大。于是「股权很险」不必均匀洒在整条期限上。过度波动若主要来自折现率消息，应更多地表现在长条价格上；可预测性同理。</p><p>信息：短条更接近即将实现的 \\(y\\)，揭示深度随到期变——Admati 的跨资产学习在期限维上有类比。本课点到为止，不重做 REE。</p><p><span class="marginnote">长期风险（Bansal–Yaron）让增长的小持续成分进入 \\(m\\)，长条可以更险。与 Lettau–Wachter 的短条更险相反，取决于哪一个因子主导。形状是模型选择，不是数据终审——终审换栏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不报告股利期货的平均回报表。那是对这条理论的测量，样本短、合成摩擦大，属于量化。下一课离开交换经济：生产技术让投资的边际成为另一套定价核，股利不再等于果实。</p><p>后课默认：股权溢价有期限结构；折现率因子与股利因子在不同到期上权重不同。总量 \\(D/P\\) 是加总坐标，不是每一条的充分统计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>股利条各自对 \\(m\\) 暴露，风险价格可以随到期变。</li><li>折现率均值回复 vs 持久增长冲击，给出相反的倾斜。</li><li>国债期限结构共享 \\(m\\)，不共享支付；不在此重写 EH。</li><li>出处：Lettau and Wachter, <em>JF</em> 2007；van Binsbergen, Brandt and Koijen, <em>JF</em> 2012。</li></ul>',10))])}const P=o(p,[["render",c]]);export{D as __pageData,P as default};
